    faq_a_bag_examples_list: "تأتي الحقيبة الجديدة مع أمثلة يمكن تغييرها أو حذفها مثل أي شيء آخر: البيت (التسوّق، وصفات، وجبات الأسبوع)، العائلة (لحظات صغيرة، قائمة لحفلة عيد ميلاد، الأنشطة والدروس)، أفكار (أفكار لعطلة الأسبوع، وأفكار للهدايا حسب مدى القرب من الشخص، وماذا تفعل بالمال الذي ادّخرته) ورحلات (أماكن تريد الذهاب إليها، أغراض الرحلة، أغراض الفندق وقائمة للسفر إلى الخارج). أما الحقيبة الموجودة من قبل فتحصل مرة واحدة على الأحدث، داخل جيوبها الخاصة.",
    faq_q_bag_examples_list: "ما الأمثلة الموجودة في حقيبتي؟",
    faq_a_nm_me1_guide: "Me – شخصيتك في New Me، في شكلها الأول (Me1). في المرة الأولى، بعد الانضمام مباشرة، تنفتح بوابة من نور يحيط بها البريق من كل جانب وتطير منها Me، تشرح ببضع ضغطات ما ينتظرك، ثم تبقى بجانب كل سؤال: أثناء اختيار الوجبات تكتب معك في كتابها، والضغط على نصيحتها يُظهر نصيحة أخرى. في النهاية تحتفل Me معك وتأخذك في جولة قصيرة – وعندما تنتهي الجولة، تبقى لها معك لحظة صغيرة أخرى. وإذا خرجت في المنتصف – من الأسئلة أو من الجولة – تفرح Me برؤيتك في المرة القادمة وتسألك إن كنت تريد المتابعة من المكان نفسه. زر «تخطي» في الأعلى يتخطى المقدمة.",
