    room_genie_again_no: "ليس الآن",
    room_genie_again_no_msg: "إذن حان الوقت لتحقيق الأهداف التي وضعتها بالفعل. وحين تصل إلى الهدف التالي – سيكون هناك شيء بانتظارك ✨",
