    faq_a_shop_holidays: "في قائمة التسوق، اضغط على الهدية: تظهر أعياد بلدك (المحدد في الإعدادات) بالترتيب، مع تواريخها – التي تُحسب تلقائيًا كل عام. اضغط على عيد لتظهر قائمة جاهزة بما يشتريه الناس له؛ كل شيء محدد (ما عدا ما هو موجود في قائمتك بالفعل)، ألغِ تحديد ما لا تحتاجه واضغط على «أضف إلى القائمة». قبل العيد بأسبوعين تظهر بطاقة صغيرة أعلى القائمة؛ وزر ✕ يخفيها حتى العيد التالي.",
    faq_q_shop_holidays: "كيف تعمل ميزة «ماذا تشتري للعيد»؟",
    shop_hol_add: "أضف إلى القائمة ({n})",
    shop_hol_added: "تمت الإضافة إلى القائمة: {n}",
    shop_hol_btn: "ماذا تشتري للعيد",
    shop_hol_items_title: "{holiday} – ماذا تشتري؟",
    shop_hol_not_now: "ليس الآن",
    faq_a_shop_delivery: "في قائمة التسوق، اضغط على الشاحنة: اختر ما في الطلب (كل شيء محدد)، ومتى يصل – اليوم أو غدًا أو في يوم آخر – وفي أي وقت (صباحًا أو ظهرًا أو مساءً، أو «وقت آخر…» لساعاتك الخاصة). تنتقل هذه العناصر إلى بطاقة «في الطريق» أعلى القائمة، مع اليوم والساعات. وعندما يحين اليوم، يظهر «هل وصل الطلب؟» في «يومي» (وفي البطاقة «هل وصل؟»). إذا وصل كل شيء، تنتقل العناصر إلى «للشراء مجددًا». وإذا كان هناك شيء ناقص، اضغط على ما لم يصل فيعود مباشرة إلى القائمة.",
    faq_a_shop_departments: "ترتّب القائمة نفسها حسب أقسام السوبرماركت – فواكه وخضار، خبز، ألبان وبيض، لحوم وأسماك، مؤن، مجمدات، مشروبات، تسالي، تنظيف، عناية شخصية، أطفال وحيوانات أليفة – لتمرّ بين الممرات بالترتيب. يُعرف القسم من اسم العنصر. إذا وقع عنصر في المكان الخطأ، اضغط عليه واختر قسمه، أو «أخرى…» لتكتب قسمك الخاص.",
    faq_a_shop_share_qty: "نعم. بجانب كل عنصر، يضيف + واحدًا آخر (×2، ×3…) ويُنقص − واحدًا. زر المشاركة أعلى قائمة التسوق يرسل القائمة كاملة، مرتّبة حسب الأقسام، عبر WhatsApp أو البريد الإلكتروني أو كنسخة.",
    faq_a_shop_two_buttons: "كلاهما يعني «تم الشراء». ✕ لشيء تشتريه مرة واحدة: يخرج من القائمة (وينتظر في الأرشيف 🗑️ تحسّبًا للخطأ). ↺ لما تشتريه مرة بعد مرة: يخرج من القائمة وينتظر في «للشراء مجددًا»؛ يفتحه الزر الصغير ↺ بجانب سلة المهملات أسفل القائمة، وضغطة واحدة هناك تعيد عنصرًا إلى القائمة. ومن «تعديل» داخله يمكنك إخراج عنصر منه. عند إضافة عنصر، تظهر الأشياء التي اشتريتها من قبل كاقتراحات، وإذا كان موجودًا في القائمة بالفعل فإنه يصبح ×2 بدل سطر ثانٍ.",
    faq_q_shop_delivery: "كيف يعمل «طلبتُ توصيلًا»؟",
