    nm_demo_saved_2: "زبادي مع جرانولا وفاكهة",
    nm_demo_title: "هكذا يتمّ التبديل",
    faq_a_new_me_challenge_journal: "عندما ينتهي تحدٍّ – كبير أو صغير أو تحدّي الأسبوع – يظهر في الاحتفال زر «📝 كيف كان؟». يفتح هذا الزر صفحة في دفتر التحديات: كيف كان الشعور (خمسة وجوه)، وما الذي ساعد، وما الذي كان صعبًا، وماذا آخذ معي من هذا – لا شيء من ذلك إلزامي، ويمكن أيضًا تركه لوقت لاحق. الدفتر ماسة في الحقيبة السحرية: كل تحدٍّ انتهى مع تاريخه وما كُتب فيه، والأحدث أولًا – الضغط على أيٍّ منها يفتحه للقراءة أو التعديل أو المشاركة (لا تتم مشاركة إلا ما في الصفحة). ويحصل التحدّي المنتهي أيضًا على ميدالية في الإنجازات، تحت «التحديات التي أنهيتُها». دفتر التحديات منفصل عن المذكّرات.",
    faq_q_new_me_challenge_journal: "ما هو دفتر التحديات؟",
