    nm_swap_time: "الوقت",
    faq_a_ai_reminder_in_text: "نعم – يكفي كتابته مع المهمة، مثلًا «غدًا الساعة 17:00 استلام الطرد، مع تذكير قبل ساعة». يُحفظ التذكير على المهمة نفسها: قبل ساعة، أو نصف ساعة، أو قبل يوم، وهكذا، و«ذكّرني» من دون وقت تعني قبل 10 دقائق. التذكير المكتوب في النص له الأولوية على حقل التذكير في النافذة نفسها.",
    faq_q_ai_reminder_in_text: "هل يمكن طلب تذكير من مساعد الذكاء الاصطناعي في الطلب نفسه؟",
    myday_meals_all_done: "تم تسجيل كل وجبات اليوم 🍽️",
    nm_tour_week_text: "تحدٍّ صغير للأسبوع. ✓ كل يوم – وفي النهاية مفتاح.",
    books_home_chip: "{title} · ص {page}",
    books_home_of: "من {total}",
    books_home_off_toast: "أُزيل الكتاب من الشاشة الرئيسية",
    books_home_on_toast: "الكتاب في الشاشة الرئيسية 📖",
    books_home_pin: "في الشاشة الرئيسية",
    books_home_q: "في أي صفحة أنا؟",
    books_home_save: "حفظ",
    faq_a_books_home_chip: "نعم. في ركن القراءة، على بطاقة كتاب قيد القراءة، المس 📌 في الشاشة الرئيسية. يظهر زرّ صغير يحمل الكتاب والصفحة تحت التحية في الشاشة الرئيسية – المسه، واكتب رقم الصفحة الجديد واحفظ، فيُسجَّل التقدّم (في ركن القراءة أيضًا). ولمس 📌 مرة أخرى يزيله. يمكن وضع عدة كتب معًا – زرّ لكل كتاب – وهو نفسه على جميع الأجهزة.",
    faq_a_new_me_week_challenge: "تحدٍّ صغير لأسبوع واحد، يختاره المرء بنفسه. في الممر توجد بطاقة كبيرة: «على ماذا تودّ العمل هذا الأسبوع؟» – المسها، واختر مجالًا (مع نفسي، مع الآخرين، التعلّم والنموّ، الهدوء، خطوات صغيرة شجاعة، البيت والروتين) وتحدّيًا، وحدّد موعد البدء. وهذه التحديات نفسها موجودة أيضًا في شاشة التحديات، تحت 🌱 التطوّر الشخصي. كل يوم يوضع ✓ على البطاقة (مع يوم حرّ واحد في الأسبوع)، وكل أسبوع ينتهي يجلب مفتاحًا جديدًا للعالم السري. أما «قراءة صفحتين في اليوم» فيُحتسب تلقائيًا من الصفحات المسجَّلة في ركن القراءة. وعند انتهاء الأسبوع، يضيفه زر «📌 إبقاؤه كمهمة يومية» إلى روتيني في الساعة المختارة، مع ✓ كل يوم. يعمل تحدٍّ واحد للأسبوع في كل مرة؛ وتستمر التحديات الكبيرة والصغيرة إلى جانبه.",
    faq_a_room_genie: "على الشرفة المطلّة على البحر، لمسة على مصباح علاء الدين تُخرج روح الغابة – وتبدأ محادثة: ما أمنيتك (ما الذي تودّ تغييره في حياتك)، وكيف سيكون الشعور حين تتحقق، وما الصعب في الطريق، وكيف يمكن تحويل الوضع الحالي إلى شيء جيد. ثم كم من الوقت سيستغرق ذلك تقريبًا، وخطوة أولى صغيرة وخطوتان أخريان، وصيغة «إذا… فإنّ…» للحظات التي يصعب فيها الأمر. وفي النهاية تظهر الأمنية كاملة خطوة بخطوة، ويمكن تحويلها إلى هدف في أهدافي (تصبح الخطوات محطّات على الدرب، بتاريخ حسب المدة المختارة؛ ويمكن تغيير كل شيء هناك) أو حفظها في المذكّرات – ثم تودّع الروح. لا يُحفظ شيء ما لم يُختر أحدهما. ومن الزيارة الثانية فصاعدًا، تسأل الروح أولًا إن كنت تودّ تغيير شيء آخر في حياتك: نعم – المحادثة نفسها؛ ليس الآن – تذكير بتحقيق الأهداف التي وُضعت بالفعل. تخرج الروح مرة واحدة في اليوم: بعد حفظ أمنية (أو بعد «ليس الآن»)، تستريح حتى الغد. وتتبع الأسئلة طريقة معروفة لتحويل الأمنية إلى خطة: أمنية، ونتيجة، وعقبة، وخطة.",
    faq_q_books_home_chip: "هل يمكن رؤية كتابي وصفحتي في الشاشة الرئيسية؟",
    faq_q_new_me_week_challenge: "ما هو تحدّي الأسبوع؟",
