    nm_me_choose: "اختيار",
    nm_me_on_screen: "على الشاشة",
    faq_a_new_me_game: "في New Me تبقى أزرار اللعبة دائمًا في المكان نفسه – في الممرّ وفي الغرفة السرية وفي كل مكان في الغابة؛ وحدها اللوحة في الوسط تتغيّر. في الأعلى: اليوم في الرحلة، والمفاتيح، والسلسلة، وطاقة اليوم (كم أُكل من الخطة)، وتحتها المهمة التالية – الوجبة التالية في موعدها (الضغط عليها يفتحها، مع ✓ أكلتها). على الجانب: اليوم كله والتحديات ورحلتي، وبجانبها تحدّي الأسبوع – أيامه السبعة و✓ لليوم. في الأسفل: الحقيبة السحرية (كل ما في New Me – خريطة العالم، ورحلتي، وقائمة التسوق، والإنجازات، ودفتر التحديات، والقياسات، وصور التقدم، والتقويم الشهري، والجدول اليومي، والتذكيرات، والقائمة PDF، والإعدادات؛ وتُفتح كشاشة مستقلة). تُظهر خريطة العالم، وهي أول ما في الحقيبة، كل أماكن الغابة – الضغط على مكان يأخذك إليه؛ وعلى المكان المقفل يظهر عدد المفاتيح التي يحتاجها. Me هي شخصيتك على درب الغابة: تبدأ كـMe1، وبعد بعض التحديات (4 مفاتيح) تكبر لتصبح Me2، وقرب النهاية (9 مفاتيح) Me3 – مع تحوّل يمكن مشاهدته. الضغط على Me يُظهر كل المراحل – ويمكن اختيار أي شخصية سبق الوصول إليها مرة أخرى، فتعود شخصية سابقة. Me تطفو – تُسحب بالإصبع أو بالفأرة، فيُفتح المدخل الذي تلمسه (والمدخل المقفل يُظهر عدد المفاتيح الناقصة). وترافقك Me أيضًا إلى كل غرفة وكل مكان، وتطفو حيث تتركها: اسحبها إلى أي مكان، واسحب الحلقة المضيئة تحتها لتديرها دورة كاملة حول نفسها؛ وهي تتّجه نحو الجهة التي تتحرك إليها (على الحاسوب: الأسهم تحرّكها، وQ وE تديرانها). في الممرّ، يعيد زر 🏠 الصغير الموجود تحت الشريط العلوي إلى الشاشة الرئيسية؛ وفي كل غرفة وكل مكان، يعيد الزر الموجود في الزاوية نفسها إلى الممرّ.",
