    faq_a_new_me_menu_build: "أولًا يسأل الاستبيان عن الوجبات التي تتناولها ومتى (وجبتان + وجبة خفيفة، أو وجبتان + عشاء خفيف، أو كلاهما)، وهل هناك شيء في المساء – للأكل أو للشرب، وما هو وفي أي ساعة. مع «وجبتان + وجبة خفيفة» تكون الوجبتان الغداء (11:30) والعشاء (19:00)، والوجبة الخفيفة في 16:00. بعد ذلك تظهر كل خيارات هذه الوجبات. اختر حتى خيارين مفضلين لكل وجبة – وتعرض القائمة «هذا أو ذاك». في بعض الخيارات (بيتا ودهن، كورن فليكس وحليب، شيء خفيف) تختار حتى 3 أشياء تحبها، كلٌّ بحصته، وتعرض القائمة «هذا أو ذاك أو ذلك»؛ والسعرات تتبع ما اخترته. والقهوة والمشروبات تعمل بالطريقة نفسها. كل اختيار متوازن، فيصل مجموع اليوم إلى 1300 أو 1500 بالضبط. للتغيير في أي وقت: ⚙️ الإعدادات ← 🍽️ بناء قائمة الطعام، أو «اختر حتى 3 مما تحب» في بطاقة الوجبة.",
