    faq_a_myday_water_toggle: "نعم. كوب الماء في «يومي» (مع + لكوب إضافي) يظهر افتراضيًا. لإخفائه، أوقف مفتاح «إظهار الماء في يومي» في الإعدادات > التخصيص والتقويم. لا يُحذف شيء – «تتبع المياه» يستمر في العمل، وإعادة تشغيل المفتاح تُرجع الكوب.",
    faq_q_myday_water_toggle: "هل يمكن إخفاء الماء في «يومي»؟",
    myday_water_toggle_label: "إظهار الماء في «يومي»",
    faq_a_routine_newme_sync: "مع New Me، يحتوي ⚙️ في «روتيني» على مفتاح «المزامنة مع New Me». عند تشغيله (الافتراضي) تظهر وجبات New Me لليوم في «يومي» وفي «روتيني» – مكان وجبات الروتين التي أُخفيت. وعند إيقافه تخرج وجبات New Me من كليهما ويعود الروتين كما كان تمامًا. لا يُحذف شيء – إعادة تشغيله تعيد كل شيء وتسأل أي وجبات في الروتين تريد إخفاءها.",
