    faq_a_food_list_languages: "بدأت قائمة الأطعمة المدمجة بأطعمة إسرائيلية وأسمائها بالعبرية. في كل اللغات الأخرى يظهر كل طعام باسمه الإنجليزي، ويجد البحث أي اسم إنجليزي يعرفه (مثلًا 'broth' يجد Clear soup)، أما الأطعمة التي لها اسم عبري فقط فلا تظهر هناك. أي شيء غير موجود في القائمة يمكن كتابته بكلماتك ببساطة – تقدير الذكاء الاصطناعي يعمل بكل اللغات.",
    faq_q_food_list_languages: "لماذا تعرض قائمة الأطعمة أسماءً بالإنجليزية، وأطعمة أقل، في لغتي؟",
    settings_copyright_line: "© 2026 جميع الحقوق محفوظة. تم تطوير التطبيق بواسطة eden zabari.",
    workout_ready_replace_btn: "استبدال",
    faq_a_sport_workout_ai: "في \"تماريني\" ← ⋯ ← \"خطة بالذكاء الاصطناعي\" (وعندما يكون الجدول فارغًا، أيضًا في البطاقة بجانب الخطط الجاهزة). أجب ببضع لمسات – كم مرة في الأسبوع، ومتى، والمكان، والمستوى، والهدف، ومعظمها فيه \"أخرى\" أيضًا – ويمكنك إضافة سطر حر، مثل ركبة حساسة أو جري 5 كم قبل الصيف. ينشئ الذكاء الاصطناعي أسبوعًا كاملًا: أنواع التمارين والأيام والأوقات والمدة والشدة والتمارين وأيام الراحة. لا يُحفظ شيء قبل المعاينة: \"وضعها في جدولي\" (بدلًا من الجدول أو بالإضافة إليه)، أو \"اقتراح آخر\" (حتى 3 مرات)، أو \"تغيير الإجابات\". الخطة معتدلة عن قصد، وإذا ذكرت ألمًا أو إصابة تحصل على خيارات لطيفة ونصيحة باستشارة مختص. وهي تستخدم حصة الذكاء الاصطناعي نفسها مثل الجدول الزمني والروتين: 5 مرات مجانًا، و60 مرة شهريًا مع بريميوم.",
    faq_q_sport_workout_ai: "كيف أنشئ خطة تمارين بالذكاء الاصطناعي؟",
