    workout_ai_replace: "بدلًا من جدولي",
    workout_ai_title: "خطة تمارين بالذكاء الاصطناعي",
    workout_ai_when_evening: "مساءً",
    workout_ai_when_label: "متى",
    workout_ai_when_morning: "صباحًا",
    workout_ai_when_noon: "ظهرًا",
    workout_ai_when_ph: "مثلًا بعد العمل، أو 17:30",
    workout_ai_working: "الخطة قيد الإعداد…",
    faq_a_sport_workout_jar: "لكل نوع تمرين نجمة بلون خاص به – الجري وردي، والمشي أخضر، والسباحة أزرق وهكذا. كل تمرين تسجّله هذا الأسبوع، من الجدول أو بشكل منفصل، يُسقط نجمته في الجرّة أعلى \"تماريني\"، وتمتلئ الجرّة حتى هدفك الأسبوعي (المسها لتغيير الهدف). عند بلوغ الهدف تتوهّج الجرّة، والجرّة الصغيرة بجانبها تعدّ كم أسبوعًا متتاليًا امتلأت.",
    faq_q_sport_workout_jar: "ما النجوم الملوّنة والجرّة في \"تماريني\"؟",
    faq_a_sport_workout_gcal: "نعم – في ⋯ ← تقويم Google (بعد ربط تقويم Google في الإعدادات). كل تمرين له وقت يصبح حدثًا يتكرر كل أسبوع في أيامه، والتغييرات في التطبيق تحدّثه. التذكيرات تأتي من التطبيق فقط، لذا لا يضيف Google تذكيرات خاصة به، ولا تظهر التمارين مرتين في التطبيق. لمسة أخرى تزيل التمارين فقط من تقويم Google.",
    faq_q_sport_workout_gcal: "هل يمكن أن تظهر تماريني في تقويم Google؟",
    workout_gcal_btn: "تقويم Google",
    workout_gcal_error: "تعذّر تحديث تقويم Google – سنحاول مجددًا مع التغيير القادم",
    workout_gcal_not_connected: "اربط تقويم Google في الإعدادات أولًا",
    workout_gcal_off_toast: "أُزيلت التمارين من تقويم Google",
    workout_gcal_on_toast: "تمارينك الآن في تقويم Google",
    faq_a_sport_workout_reminder: "نعم – داخل التمرين، تذكير: قبل 10 دقائق أو 30 دقيقة أو ساعة، أو وقت مخصص (يحتاج التمرين إلى وقت). يرنّ مثل باقي التذكيرات، مرة واحدة وفي مكان واحد: في التطبيق إن كان مفتوحًا، وإلا على هاتفك. \"تم\" يسجل التمرين في السجل، و\"ليس بعد\" يذكّر مرة أخرى بعد 5 دقائق.",
    faq_q_sport_workout_reminder: "هل يمكن أن يصلني تذكير قبل التمرين؟",
    workout_reminder_30min: "30 دقيقة قبل",
    workout_reminder_label: "تذكير",
    workout_reminder_need_time: "أضف وقتًا ليصلك تذكير",
    faq_a_sport_workout_share: "في ⋯ ← مشاركة يتحول الأسبوع إلى صورة زجاجية بألوان المظهر، مع رابط هادئ للتطبيق (على الهاتف تذهب مباشرة إلى قائمة المشاركة، وعلى الكمبيوتر تُحفظ الصورة). ⋯ ← PDF للطباعة يفتح صفحة نظيفة للأسبوع كله، مع مربع للتأشير بجانب كل تمرين وحركة – اختر \"حفظ كـ PDF\" أو اطبعها. وتظهر الخطة أيضًا في تقرير البيانات في الإعدادات، في قسم الرياضة.",
    faq_q_sport_workout_share: "كيف أشارك أسبوع التمارين أو أطبعه؟",
    share_image_saved: "حُفظت الصورة – يمكنك إرفاقها",
    share_save_image: "حفظ الصورة",
    workout_pdf_btn: "PDF للطباعة",
    workout_share_btn: "مشاركة",
    faq_a_sport_workout_board: "في ⋯ ← لوحة الأسبوع كل يوم عمود: اسحب التمرين إلى يوم آخر (على الهاتف، اضغط مطولًا أولًا). داخل التمرين، \"في روتيني أيضًا\" يضعه في روتينك في وقته وأيامه، وتبقى التغييرات متزامنة في الاتجاهين؛ ومن عنصر في روتيني، \"إضافة إلى تماريني\" يفعل العكس. ✓ في أي منهما يُحتسب في الاثنين، وفي يومي يظهر مرة واحدة – في الشارة بجانب الماء.",
    faq_q_sport_workout_board: "كيف أنقل تمرينًا إلى يوم آخر وأربطه بروتيني؟",
    routine_in_workouts_btn: "فتح في تماريني",
    routine_to_workout_btn: "إضافة إلى تماريني",
    routine_to_workout_done: "أُضيف إلى تماريني 💪",
    workout_delete_confirm_routine: "سيُزال من الخطة ومن روتيني. التمارين المسجلة في السجل تبقى.",
    workout_moved: "نُقل إلى {day}",
    workout_routine_need_time: "أضف وقتًا لوضعه في روتيني",
    workout_routine_toggle: "في روتيني أيضًا",
    workout_view_board: "لوحة الأسبوع",
    workout_view_timeline: "خط زمني",
    faq_a_sport_workout_plan: "في متابعة التمارين، تحت \"تماريني\": + تمرين – النوع والأيام والوقت والمدة والشدة والمكان (و\"أخرى\" أيضًا). تمارين القوة والوظيفية والسباحة يمكن أن تضم قائمة تمارين، و\"راحة\" يحدد يوم راحة. ويمكن البدء بخطة جاهزة. تمرين اليوم يظهر كبيرًا والأسبوع كله تحته؛ و✓ يسجله في سجل التمارين مع شدته. في ⋯ تحدد هدفًا أسبوعيًا (تمارين أو دقائق)، وكل تمرين تنجزه يُسقط نجمته في الجرّة.",
    faq_a_sport_workout_today: "في يومي، بجانب الماء، شارة صغيرة تعرض تمرين اليوم – لمسة تفتح التفاصيل و✓ و▶. ▶ يبدأ مؤقتًا يستمر في الشارة على الشاشة الرئيسية، و\"إنهاء\" يسجل التمرين بالوقت الحقيقي. إذا كان تحدي \"أسبوعان من الحركة\" في New Me جاريًا، يُحتسب فيه التمرين المسجل تلقائيًا.",
    faq_q_sport_workout_plan: "كيف أخطط أسبوع التمارين؟",
