    faq_a_new_me_magic_themes: "خمس سمات متلألئة مضمّنة في New Me: الغابة المسحورة وغبار النجوم وجنية الورود والشفق السحري والغروب الذهبي. اختر واحدة داخل New Me (⚙️ الإعدادات > الألوان) أو في الإعدادات > المظهر والعرض، فترسم فرشاة من البريق الشاشة بها. تضيف السمة السحرية بريقًا في التطبيق كله وعند كل لمسة. يمكنك العودة إلى أي سمة أخرى في أي وقت.",
