    apptour_focus_text: "كل شيء يتنحى جانبًا إلا الشيء الوحيد الآن، مع ✓ كبيرة. ثم يظهر التالي.",
    apptour_m_presets_text: "وجباتك المحفوظة في مكان واحد: بحث، والمستخدمة مؤخرًا، وحسب وقت اليوم – و＋ يضيف وجبة إلى اليوم.",
    apptour_night_text: "🌙 يجعل التطبيق كله داكنًا، و☀️ يعيد النهار.",
    apptour_noteline_text: "اكتب واضغط ➤ فيُحفظ في ملاحظاتك. و📝 في أول السطر تحوّل إلى 🛒 التسوق أو 🍎 وجبة محفوظة.",
    apptour_search_text: "الملاحظات والتسوق والتقويم والوصفات والدفاتر والأهداف والجداول والكتب – بحث واحد يجد كل شيء.",
    faq_a_new_me_ai_menu: "قبل القائمة يسأل الاستبيان عن الوجبات التي تتناولها ومتى (وجبتان + وجبة خفيفة، أو وجبتان + عشاء خفيف، أو كلاهما)، وهل تتناول شيئًا صغيرًا في المساء وفي أي ساعة، وما الذي لا تأكله، وكيف تشرب القهوة أو الشاي. ثم يُعدّ الذكاء الاصطناعي 3 خيارات لكل وجبة – كل منها بحجم حصتها من اليوم، فيبقى مجموع اليوم 1300 أو 1500 بالضبط – إضافة إلى أفكار للمشروبات تُحفظ كمشروباتك الثابتة. اختر حتى خيارين مفضلين لكل وجبة؛ خيارات القائمة الأصلية تحتها مباشرة، وفي 🔄 التبديل تظهر بعد قائمتك الشخصية. 🔄 خيارات أخرى يُعدّ مجموعة جديدة (3 مرات في كل استبيان). لتغيير إجاباتك أو إعداد قائمة جديدة في أي وقت: ⚙️ الإعدادات ← ✨ قائمة شخصية (AI).",
