    settings_sub_status_newme: "بريميوم مشمول في New Me الخاص بك.",
    room_back_to_shelf: "إلى الرف",
    faq_a_new_me_day_total: "كل يوم يصل إلى الخطة بالضبط: الوجبات، ونحو 150 سعرة للقهوة والمشروبات خلال اليوم، وما اختير للمساء – شيء صغير للأكل أو شيء للشرب. للمساء اختر حتى 3 مما تحب (مثلًا موزة، أو لبن زبادي، أو مربّعان من الشوكولاتة الداكنة؛ أو شاي أعشاب، أو شاي مع قليل من الحليب، أو حليب دافئ)، وسعراتها تُؤخذ من الوجبات. كل اختيار يتوازن وحده: خيار أصغر أو أكبر، وجبة محذوفة، الفطور الصغير والوجبة الصغيرة التي تأتي معه، أو المساء – يُضاف الفرق إلى الوجبات أو يُطرح منها، كلٌّ حسب حجمها، وتحت كل وجبة مكتوب كم (+ أو −) وماذا يمكن إضافته أو تركه. الوجبة المعلَّمة تبقى كما سُجِّلت. في الاستبيان تُظهر كل وجبة تعديلها، ويعرض مربع صغير الوجبات والمشروبات والمساء والمجموع. تشتهي شيئًا آخر في ذلك اليوم؟ المهم أن يبقى المجموع بنفس السعرات أو أقل.",
    faq_q_new_me_day_total: "كيف يصل يوم New Me إلى 1,300 / 1,500 بالضبط، وأين تُحسب المشروبات؟",
