    books_quotes_chip: "اقتباسات",
    faq_a_book_quotes: "على الرف في الغرفة السرية (اقتباسات)، أو عبر الشارة الصغيرة 💬 اقتباسات في ركن القراءة – إنها القائمة نفسها. اضغط \"+ اقتباس\"، اكتب الجملة واختر الكتاب من ركن القراءة، أو اكتب عنوانًا آخر عبر \"✏️ أخرى\"؛ المؤلف اختياري. ✏️ يعدّل الاقتباس و🗑️ يحذفه. الاقتباسات فواصل كتب تمرّرها – و🎨 في الأعلى يبدّل إلى صور أو إلى جدار من البطاقات.",
    faq_a_room_wish_jar: "على الرف في الغرفة السرية برطمان زجاجي للأحلام. اضغط على البرطمان الصغير في الرف العلوي (أو الرف > برطمان الأمنيات) واكتب كيف تريد أن تبدو حياتك – بلا حدود، بلا صح أو خطأ. كل أمنية تُطوى في ورقة وتسقط في البرطمان. «اسحب ورقة» تفتح واحدة عشوائيًا، ويمكن أيضًا فتح كل ورقة بمفردها. بدءًا من المرة الثانية التي تفتح فيها الأمنية نفسها، يمكنك تحويلها إلى هدف وتقسيمه إلى خطوات صغيرة. مرة في الأسبوع تظهر ورقة لطيفة بإحدى أمنياتك – بلا ضغط، مجرد تذكير بوجهتك.",
    faq_q_book_quotes: "أين أحفظ اقتباسات من كتب أحببتها؟",
