    faq_a_saved_meals_page: "للوجبات المحفوظة صفحة خاصة بها: التغذية والمقاييس > ⭐ الوجبات المحفوظة (أو ⭐ في القائمة). البحث في الأعلى يجد وجبة بالاسم أو بأحد المكونات، و\"استُخدمت مؤخرًا\" تُظهر ما أضفته مؤخرًا، والتبويبات (فطور، غداء، عشاء، شوربات…) تُظهر كل وقت من اليوم. \"+ لليوم\" يضيف وجبة إلى متتبع الوجبات اليومي لليوم، في الخانة الفارغة التالية. اضغط على وجبة لتعديلها أو حذفها، و＋ في الأعلى يضيف وجبة جديدة.",
