    presets_tab_snack: "وجبات خفيفة",
    presets_tab_soup: "شوربات",
    presets_tab_sweet: "حلويات",
    faq_a_notes_sticky_look: "الملاحظات قائمة قصيرة من بطاقات زجاجية – 🎨 في أعلى الملاحظات يغيّر مظهر الملاحظات كلها: القائمة، وأزرار الأيام في الأعلى، والنافذة التي تُكتب فيها الملاحظة – زجاج أو قائمة بسيطة أو بطاقات أو شريط ملوّن. الملاحظة التي تُسحب تحتفظ بمظهرها ولونها تمامًا. اضغط على نص الملاحظة لفتحها – هناك يمكنك تعديلها وتغيير ألوانها ومعرفة متى كُتبت آخر مرة. اضغط على ○ عند إنجازها، و× ينقلها إلى الأرشيف (🗑️ في أسفل القائمة يعيدها). اسحبها من ⠿ لتغيير الترتيب، أو إلى ما تحت «لاحقًا»، أو إلى يوم في الأعلى. ! تعلّم الملاحظة كعاجلة – فترتفع بلطف إلى الصفوف الأولى مع وسم صغير «عاجل»؛ وضغطة أخرى تزيل العلامة.",
    faq_q_notes_sticky_look: "كيف أفتح ملاحظة أو أعدّلها أو أزيلها؟",
    note_to_archive_btn: "نقل إلى الأرشيف",
    faq_a_routine_clash: "إذا كان في ذلك الوقت بند آخر في الأيام نفسها، تظهر خياران: «استبدال» – البند الجديد يأخذ هذا الوقت وتختار وقتًا للبند السابق (عند تعديل بند موجود يُقترح وقته السابق، فيتبادلان ببساطة)، أو «الاثنان معًا» – يبقيان في الوقت نفسه، واحد تحت الآخر. وإذا كانت الأيام مختلفة (مثلًا أحدهما من الأحد إلى الخميس والآخر يوم الجمعة) فلا يظهر أي سؤال.",
