    faq_a_new_me_coffee: "تحت قائمة اليوم يوجد ملخّص قصير: كم سعرة مجموع كل وجبات اليوم، وكم بقي للقهوة والمشروبات، وأزرار للقهوة والمشروبات التي اختيرت – ضغطة واحدة تضيفها إلى المشروبات. وفي «اختر حتى 3 مما تحب» تحت الأزرار (وفي الاستبيان أيضًا) تختار ما يظهر: ماء / صودا، شاي أعشاب، مشروب دايت، قهوة سوداء / أمريكانو (~5)، شاي مع قليل من الحليب (~25)، قهوة أساسها الماء مع حتى 100 مل حليب أو بديل نباتي (~50)، شوكولاتة ساخنة خفيفة، حليب دافئ أو قهوة عادية / لاتيه (~120).",
