    faq_a_recipe_examples: "تحت وصفاتك توجد وصفات نموذجية: فطور وسلطات وشوربات وأطباق رئيسية وأطباق جانبية ووجبات خفيفة وحلويات وأطباق نباتية صرفة، ولكل منها وقت التحضير والسعرات لكل حصة وكم غرامًا تزن الحصة الواحدة. اضغط على وصفة لفتحها، و«حفظ في وصفاتي» ينشئ نسختك الخاصة التي يمكنك تعديلها. وسوم الفئات تُصفّي، والضغط على الوسم نفسه مرة أخرى يعرض كل شيء.",
    faq_a_recipe_grams: "داخل الوصفة، بجانب السعرات، مكتوب «حصة واحدة ≈ X غ». في وصفاتك الخاصة املأ «غرامات لكل حصة» (ووقت التحضير إن أردت) في نموذج الوصفة؛ كلاهما اختياري، والوقت يظهر على الشريط الملوّن للوصفة.",
