    recipes_examples_title: "وصفات نموذجية",
    faq_a_recipe_scan_multi: "نعم. في «إضافة وصفة» اضغط 📷 واختر صورة واحدة أو عدة صور (حتى 6، ويصلح ملف PDF أيضًا). تظهر كل صورة في قائمة قصيرة تختار فيها ما تحتويه: الكل أو المكونات أو التحضير، و«➕ صورة أخرى» تضيف المزيد. ثم اضغط «✨ مسح الوصفة»: يجمع الذكاء الاصطناعي كل شيء في وصفة واحدة، بالترتيب ودون أسطر مكررة، ويُحسب ذلك مسحًا واحدًا. وتُفتح هنا أيضًا عدة صور تُختار من 📷 صورة في مساعد الذكاء الاصطناعي.",
    faq_q_recipe_scan_multi: "هل يمكنني مسح وصفة واحدة من عدة صور، مثل المكونات والخطوات كلٌّ على حدة، أو صفحتين؟",
