    faq_a_note_written_at: "اضغط على نص الملاحظة لفتحها. في الداخل، تحت النص، يظهر وقت آخر كتابة لها بالتاريخ والساعة بالضبط. تغيير النص نفسه فقط يحدّثه: الأرشفة والاستعادة ووضع علامة ✓ والألوان ونقل الملاحظة لا تغيّره.",
