    faq_a_new_me_month: "في الحقيبة السحرية ← التقويم الشهري: كل يوم ملوّن حسب عدد الوجبات المؤشَّرة، والسهمان ‹ › ينتقلان بين الأشهر، وتحت التقويم يظهر متوسط السعرات اليومية في الشهر. لمس يوم يُظهر عدد الوجبات المؤشَّرة وكم سعرة أُكلت فيه.",
    faq_q_new_me_month: "أين أرى الشهر السابق ومتوسط السعرات في New Me؟",
