    nm_extra_line_small: "{n} سعرة لهذه الوجبة، من الفطور الصغير – مثلًا {ideas}",
    faq_a_new_me_small_breakfast: "فطور خفيف (نحو 170 سعرة): خبز بيتا من الإسبلت (حتى 100 سعرة) مع دهن أو جبن، إلى جانب خضار – اختر حتى 3 مما تحب، مثلًا ملعقة صغيرة من الشوكولاتة القابلة للدهن، أو ملعقة صغيرة من زبدة الفول السوداني، أو شريحة جبن أصفر (حتى 22%). ولأنه صغير، تأتي معه «ووجبة صغيرة إضافية» في وقت آخر (بعده بساعة ونصف، مثلًا 11:30 ← 13:00 – ويمكن اختيار أي وقت آخر): بيتا أخرى ودهن، أو زبادي بروتين وفاكهة، أو كعك الأرز وجبن، أو حبوب وحليب، أو نصف بيتا وبيض – حتى نحو 200 سعرة، مع ✓ خاصة بها. وما يبقى بعد ذلك يتوزع على باقي الوجبات، وكل وجبة تُظهر كم أُضيف إليها، فيبقى مجموع اليوم كما في الخطة. يمكن اختياره في الاستبيان، أو التبديل إليه لليوم فقط عبر 🔄 – مثلًا عند تأخر الفطور.",
