    faq_a_ai_icon: "نعم – في الإعدادات > المظهر والعرض. الفقاعة الناعمة هي الافتراضية، ومع Premium يمكن أيضًا اختيار دماغ عائم أو روبوت.",
    faq_a_new_me_favorites: "نعم. في الاستبيان (وعند إعادته من الإعدادات) يمكن اختيار حتى خيارين لكل وجبة. يظهر الأول في القائمة، وتحته سطر «أو» للثاني – لمسه يبدّل إليه لليوم فقط. وإذا لم يُتناول الفطور في وقته، فإن «⏰ لاحقًا» يؤجّله إلى وقت لاحق من اليوم دون تغيير السعرات.",
    faq_a_theme_mode: "بعض السمات الخاصة تبدو أجمل في الوضع الداكن – ألوان مائية، الشفق القطبي، باربي وسمتا اللمعان – لذا فاختيار إحداها ينقل التطبيق إلى الوضع الداكن، واختيار أي سمة أخرى (الصاروخ أيضًا) ينقله إلى الفاتح. الأسود والرمادي الداكن يبقيان داكنين. ويمكن دائمًا التغيير بعد ذلك عبر 🌙 في القائمة أو \"الوضع الفاتح\" في الإعدادات.",
    faq_a_water_month: "في متابعة الماء. يظهر بجانب كل إدخال في سجل اليوم الوقتُ الذي أُضيف فيه، ويفتح \"جدول شهري\" الشهر كله: يظهر في كل يوم عدد اللترات المشروبة (✓ عند بلوغ الهدف اليومي)، ولمس يوم يعرض إدخالاته مع أوقاتها.",
