    faq_a_room_records: "الفونوغراف موجود في الغرفة منذ البداية، على جذع الشجرة بجانب الكرسي. أسطواناته تفتح على يوتيوب المقاطع الرسمية لأغانٍ ناجحة كبيرة من السنوات الأخيرة، وتحتها خمسة ألحان هادئة تُعزف هنا في الغرفة – تدور الأسطوانة أثناء العزف، و«⏹ إيقاف» يوقف الموسيقى.",
    faq_a_room_roof_gifts: "يأتيان مع المفتاح الثامن. لمسة على التلسكوب تتيح لك النظر عبره: سماء الليل عن قرب – اسحب (أو استخدم الأسهم) لتنظر حولك – وتشكّل تحدياتك المنتهية فيها كوكبة، نجمة لكل تحدٍّ، ولمس النجمة يُظهر أيّ تحدٍّ كان. ولمسة على الصندوق الصغير تفتحه – وهو فارغ في الوقت الحالي – ولمسة أخرى تغلقه.",
