    faq_a_ai_chat_food_fix: "نعم. تحت الرد في المحادثة يوجد ✏️ تصحيح السعرات / البروتين: تُغيَّر الأرقام ثم «حفظ». يتغيّر فقط ما أُضيف للتو – حتى لو انضمّ إلى وجبة خفيفة كانت موجودة. قد يخطئ الذكاء الاصطناعي، لذا تستحق نظرة سريعة.",
    faq_a_new_me_home_btn: "لمن لديه New Me، يفتح 💎 صغير بجانب وضع التركيز أعلى الشاشة الرئيسية قائمة اليوم. وتظهر وجبات اليوم أيضًا في «يومي»، ولكل منها ✓.",
    faq_a_routine_item_days: "نعم. بلمسة على العنصر في «روتيني» تُختار أيامه تحت 📅 الأيام – مثلًا من الاثنين إلى الجمعة فقط. في الأيام الأخرى لا يظهر في «يومي» ولا تكون له ✓، وفي «روتيني» يبقى باهتًا قليلًا وبجانبه أيامه. والبطاقة التي تسأل عن عنصر بعد 3 أيام بلا ✓ تحسب أيام العنصر فقط.",
