    faq_a_home_note_line: "اكتب في السطر الموجود في وسط الشاشة الرئيسية واضغط ➤ (أو Enter) – فتُحفظ في الملاحظات. اضغط 📝 في بداية السطر فيتحوّل إلى 🛒: وعندها يذهب ما تكتبه إلى قائمة التسوق. اضغط مرة أخرى لـ 🍎: اكتب بضعة أحرف فتظهر وجباتك المحفوظة المطابقة، ولمسة واحدة تسجّل إحداها في وجبات اليوم. ومع 🎤 يمكنك قولها بصوتك فقط.",
    faq_a_night_mode: "افتح القائمة ☰ واضغط 🌙 في الأعلى – يصبح التطبيق كله داكنًا. و☀️ في المكان نفسه يُعيد النهار. وهو موجود أيضًا في الإعدادات، ضمن الوضع الفاتح.",
