    menu_night_mode: "الوضع الليلي",
    faq_a_secret_room_yoga: "في نهاية درب الغابة بوابة متوهّجة، وخلفها، بجانب شلال، تجلس كائنات الغابة – لومي وبوفي ونيكسي وسباركليت – على سجّاداتها في نصف دائرة، وتجلس فلورا، معلّمة اليوغا، قبالتها على السجّادة الوحيدة فوق الصخرة. المس فلورا: تفتح عينيها، ويقترب كل شيء، وتبدأ المحادثة ببطء، مع وقت للقراءة – تسأل فلورا كيف حال الجميع، ويجيب كل كائن باسمه (وبجانب كل سطر رسم صغير لمن يتكلم)، ثم تسألك كيف تشعر مع المقرّبين منك. تستمر المحادثة حسب إجاباتك: أشخاص طيبون، أو شخص يصعب التعامل معه، أو شيء من الوحدة. كل طريق ينتهي بمهمة صغيرة (يمكن إضافتها مباشرة إلى «يومي»؛ وعندما تكون المهمة كتابة شيء ما، يوجد مكان لكتابته، ويُحفظ في المذكّرات السحرية) ووضعية مع ثلاثة أنفاس معًا. ↩ يعود خطوة إلى الوراء و✦ يبدأ محادثة جديدة. المفتاح التالي يفتح الشلال: الجلوس على الصخرة يُخفي كل شيء ولا يبقى إلا صوت الماء. وعند الانحناء فوق البركة يطفو سؤال من الماء – ماذا كانت ذاتك الحقيقية ستفعل اليوم؟ – وتصبح الإجابة مهمة صغيرة في «يومي». إنها لحظة لطيفة، وليست بديلًا عن الحديث مع مختص.",
    faq_q_secret_room_yoga: "ماذا يحدث في اليوغا في الغابة؟",
