    routine_time_taken: "يوجد شيء بالفعل في هذا الوقت: {title}",
    faq_a_new_me_times: "في الاستبيان في البداية، وفي أي وقت من إعدادات New Me ← «أوقات الوجبات». إذا كان في روتينك أوقات للوجبات، تؤخذ من هناك – ويمكن إخفاء وجبات الروتين وعرض وجبات New Me مكانها. وإن لم يكن، تختار عدد الوجبات في اليوم (وجبتان + وجبة خفيفة / وجبتان + عشاء خفيف / وجبتان + وجبة خفيفة + عشاء خفيف) وموعد كل واحدة. مع «وجبتان + وجبة خفيفة» تكون: الغداء في 11:30، ووجبة خفيفة في 16:00، والعشاء في 19:00 (ويمكن تغيير أي منها). هذه أوقات وجباتك في كل مكان: في الممر، وفي «يومي»، وفي «روتيني»، وفي التذكيرات. مهما كان الاختيار، تبقى سعرات اليوم كما هي: ما يُحذف يُوزَّع على باقي الوجبات.",
