    faq_a_routine_exact_time: "نعم. عندما تصف روتينًا للذكاء الاصطناعي بوقت دقيق (مثل \"16:10 تداول\")، يُحفظ كما هو تمامًا دون تقريبه إلى ساعة كاملة. كل ما هو مكتوب في روتينك يظهر دائمًا على اللوحة حتى لو لم تُختر ساعته في إعدادات الساعات، وإزالة ساعة فيها شيء تطلب التأكيد أولًا. يمكنك أيضًا تغيير الوقت يدويًا: المس الوقت في نافذة العنصر واختر الساعة والدقائق.",
    faq_q_routine_exact_time: "هل يمكن أن يكون في روتيني وقت دقيق، مثل 16:10؟",
