    routine_daysoff_what: "وما الروتين في هذه الأيام؟",
    routine_daysoff_which: "أي أيام؟",
    faq_a_secret_room_diary: "أنت فقط. تُحفظ صفحات المذكّرات في حسابك، فهي موجودة على كل أجهزتك ولا يمكن لأحد غيرك رؤيتها. تفتحها المذكّرات السحرية الموضوعة على المكتب في الغرفة السرية، وكذلك المذكّرات في ركن الموسيقى. تحت الصفحة الجديدة يوجد جدول شهري مطوي: نقطة تميّز كل يوم فيه صفحة، ولمس اليوم يفتح صفحاته، ويمكن هناك أيضًا حذف صفحة. عندما تكون المذكّرات مفتوحة، يمكن أيضًا إضافتها إلى القائمة الرئيسية – بالمفتاح الموجود في المذكّرات نفسها أو في إعدادات New Me.",
    faq_a_secret_room_places: "كل مدخل في بوابة الغابة يُفتح بمفتاحه الخاص. خلفها: الشرفة المطلّة على البحر (على الطاولة الصغيرة مصباح علاء الدين – لمسة، فتخرج منه روح الغابة في ضباب سحري، تدور وتبدأ محادثة عن أمنيتك – انظر «ماذا يفعل جنّي المصباح؟»)، والغيتار والمذكّرات (الغيتار يعزف لحنًا قصيرًا هادئًا ويتوقف من تلقاء نفسه، وكل واحدة من الأسطوانات الثلاث المعلّقة على الشجرة تعزف لحنها السحري الخاص بها – ولمسة أخرى توقفه – والمذكّرات على جذع الشجرة للكتابة)، وغرفة التنفّس (بحيرة هادئة عند الغروب: يطفو على الماء فانوس لوتس، المسه واكتب أمنية فيبتعد معها، بعيدًا في أعماق البحيرة؛ ويمكنك بالعصا السحرية أن تكتب على الرمل ما تودّ التخلي عنه ويبقى حتى تمحوه بإصبعك)، ودرب الغابة (يُفتح في الليل، ولمس الفوانيس يحوّله إلى النهار؛ وتتدلّى من الفرع الكبير أرجوحة سحرية، والمقعد للجلوس، ولمس اللافتة يقرّبها: لوح عليه ستة أسئلة صغيرة لوضع علامة عليها). على المدخل المقفل يظهر عدد المفاتيح المتبقية. في نهاية الدرب، تقود بوابة متوهّجة إلى اليوغا بجانب الشلال، ومن هناك إلى الشلال نفسه.",
