    dev_weather_preview_label: "معاينة – على حسابك فقط:",
    faq_a_ai_chat: "الضغط على الفقاعة يفتح محادثة. يمكن اختيار ما يجب فعله – شيء للتقويم، ما أُكل، صورة وصفة أو جدول جديد – أو مجرد الكتابة، والمساعد يفهم وحده. للتقويم يمكن اختيار مرة واحدة أو كل أسبوع أو كل يوم. يصل الرد في المحادثة، ومن هناك يمكن الانتقال إلى شيء آخر أو فتح التقويم / ما أُكل.",
    faq_a_new_me_hall: "يُفتح New Me على بوابة غابة سحرية، وكل مدخل فيها هو مكان: الباب المستدير في الشجرة العملاقة يؤدي إلى الغرفة السرية، والجذع المجوّف إلى الشرفة المطلّة على البحر، وبيت الفطر إلى الغيتار والمذكّرات، وقوس الصفصاف الصغير إلى غرفة التنفّس، وقوس الصفصاف الكبير إلى درب الغابة، وقوس الزهور ذو السلّم يصعد إلى سطح النجوم بعد أن يُفتح. على المدخل المقفل يظهر قفل. على الدرب تطفو شخصيتك، Me، ومن حولها أزرار اللعبة: المهمة التالية، وتحدّي الأسبوع، والحقيبة السحرية مع كل New Me، وخريطة العالم، والأدوات. والضغط على المفاتيح في الأعلى يشرح كيف تُكسب المفاتيح.",
    faq_a_new_me_routine_meals: "عندما تُحدَّد وجبات في New Me ويحتوي روتيني أيضًا على وجبات، يسأل New Me إن كان يجب إخفاؤها وعرض وجبات New Me مكانها – حتى لا يظهر شيء مرتين. عندها يعرض روتيني وجبات New Me في أوقاتها، مع 💎 و✓؛ والضغط على اسم وجبة يفتح نافذة لاختيار وجبة أخرى أو تغيير وقتها، هناك مباشرة فوق الروتين. لا يُحذف شيء: تعود من ⚙️ إعدادات New Me ← وجبات في الروتين، أو بإيقاف «المزامنة مع New Me» في ⚙️ روتيني. وبدون New Me فعّال تعود وحدها.",
    faq_a_room_computer: "إنها محادثة صغيرة تبدأ بـ«كيف يمضي اليوم حتى الآن؟» – جيد أو مزدحم أو صعب – وتستمر خطوة بخطوة، حتى مهمة صغيرة واحدة في النهاية (يمكن أيضًا إدخالها مباشرة إلى «يومي»). يمكن الضغط على الإجابات أو الكتابة بحرية – وما يُكتب يرتبط بأقرب إجابة. «↩ رجوع» يعود خطوة واحدة للإجابة بشكل مختلف، و«محادثة جديدة» تبدأ من جديد في أي لحظة. بعد يوم مزدحم أو صعب يمكن العودة إلى الحاسوب لاحقًا في اليوم نفسه: «عدتُ...» يكمل المحادثة. الضوء الأخضر في الأسفل يطفئ الحاسوب ويشغّله. تُحفظ الاختيارات فقط، على هذا الجهاز فقط وحتى نهاية اليوم فقط.",
    faq_q_ai_chat: "كيف أتحدث مع المساعد؟",
    faq_q_new_me_hall: "ما هو الممرّ في New Me؟",
