    dictation_mic_denied: "الميكروفون محظور – اسمح به من 🔒 بجانب العنوان في المتصفح، أو من إعدادات الهاتف",
    faq_a_dictation: "نعم – المس الميكروفون 🎤 في زاوية الملاحظة السريعة أو صفحة كتابة في الدفتر، وتحدّث: تُكتب الكلمات أثناء الكلام، بلغة التطبيق. المسه مرة أخرى للإيقاف. في المرة الأولى يطلب المتصفح إذنًا لاستخدام الميكروفون. يعمل في Chrome / أندرويد وفي Safari على iPhone. على الكمبيوتر تحتاج إلى ميكروفون ومتصفح مثل Chrome أو Edge أو Safari – وإن نقص شيء، تقول الرسالة ما هو بالضبط.",
    faq_q_dictation: "هل يمكنني التحدث بدلًا من الكتابة؟",
    faq_a_secret_room: "غرفة لك وحدك داخل New Me – بيت داخل شجرة عملاقة. ترى جدارًا واحدًا في كل مرة وتدور بالأسهم (أو بالسحب). يأتي المفتاح الأول بعد ✓ على وجبة في 3 أيام مختلفة ويفتح الباب – ومعه الغرفة كلها: الحاسوب، واللعبة، والفونوغراف، والرف وفيه المكتبة، والقطة. ثم يمنح كل تحدٍّ ينتهي (وتحدّي الأسبوع أيضًا) مفتاحًا يفتح المكان التالي: سطح النجوم، والشرفة المطلّة على البحر، والغيتار والمذكّرات، وغرفة التنفّس، ودرب الغابة مع اليوغا، والشلال، ومفاجأة على السطح – والتحدي الثامن يجلب زجاجة من البحر وفيها الرسالة من الماضي. عندما يُفتح شيء، يدلّك سهم على الطريق إليه. ويُفتح أيضًا الباب الصغير في أسفل آلة الألعاب – والخزانة الصغيرة التي خلفه فارغة حاليًا. على سطح النجوم، النجمة التي تلمسها تسقط كشهاب، والقطة تجلس على الوسادة.",
