    faq_a_steps_in_sport: "في أعلى «متابعة التمارين»، في شريط صغير: خطوات اليوم وهذا الأسبوع. ستُحتسب الخطوات تلقائيًا عندما يتصل التطبيق بـ Google Fit / Apple Health في نسخة الهاتف، وزر 🔗 بجانبها يشرح ذلك.",
    faq_q_steps_in_sport: "أين عداد الخطوات اليومي؟",
    sport_steps_today_label: "خطوة اليوم",
    sport_steps_week_label: "هذا الأسبوع",
    faq_a_reminders_one_place: "يصل كل تذكير مرة واحدة وفي مكان واحد. إذا كان التطبيق مفتوحًا أمامك (على الكمبيوتر أو الآيباد أو الهاتف) يظهر هناك؛ وإلا يصل كإشعار إلى الهاتف فقط. «✅ تم، شكرًا!» أو «فهمت!» في أي مكان يغلقه على كل الأجهزة، ولا يعود. «ليس بعد» يؤجله: يعود كل 5 دقائق، وفي كل مرة في مكان واحد. وضع علامة ✓ على المهمة في القائمة يُحتسب أيضًا «تم». لتلقي الإشعارات على الكمبيوتر والجهاز اللوحي أيضًا، يكفي تفعيل «على الكمبيوتر والجهاز اللوحي أيضًا» في الإعدادات > الإشعارات.",
    faq_q_reminders_one_place: "لماذا يصل التذكير مرة واحدة فقط، وإلى الهاتف فقط؟",
    reminder_all_devices_hint: "افتراضيًا يصل كل تذكير مرة واحدة وفي مكان واحد: إلى الهاتف، أو إلى الجهاز الذي يكون التطبيق مفتوحًا عليه أمامك. «تم» أو «فهمت» في مكان واحد يغلقه في كل مكان.",
    reminder_all_devices_label: "على الكمبيوتر والجهاز اللوحي أيضًا",
    myday_water_info: "8 أكواب ماء متوسطة / صغيرة تساوي في المتوسط نحو لترين",
    faq_a_good_things: "في المساء (من الساعة 18:00) يظهر زر صغير تحت التاريخ: تُكتب فيه حتى 3 أشياء جميلة حدثت اليوم – حتى شيء واحد يكفي. تُحفظ، وفي \"الأيام السابقة\" يمكن رؤية ما كُتب من قبل. \"ليس الليلة\" يخفيه حتى الغد، ويمكن إيقافه تمامًا من الإعدادات > التخصيص والتقويم.",
    faq_a_home_countdown: "ضع ⭐ على حدث في التقويم (النجمة بجانبه في قائمة الأحداث). أقرب حدث مميّز بنجمة خلال الـ 100 يوم القادمة يظهر تحت التاريخ – \"بعد 3 أيام · عيد ميلاد أمي\" أو \"غدًا · …\" أو \"اليوم · …\". النقر عليه ينتقل إلى ذلك اليوم في التقويم.",
    faq_a_home_streak: "يعدّ كم يومًا متتاليًا كان فيه ✓ واحد على الأقل – أي شيء في يومي أو روتيني أو أهدافي أو New Me. يظهر ابتداءً من يومين. إذا لم يوجد ✓ اليوم بعد، فالسلسلة لم تنقطع – ما زال هناك اليوم كله. وإذا انتهت، تختفي ببساطة بهدوء، بلا شعور بالذنب.",
    faq_a_home_weather: "يُفعَّل \"الطقس في سماء الشاشة الرئيسية\" من الإعدادات > التخصيص والتقويم مع السماح بالموقع. عندها تُظهر سماء الشاشة الرئيسية الطقس الحقيقي في مكانك – شمس (أو قمر ونجوم ليلًا)، غيوم، مطر، ثلج، عاصفة أو ضباب – في كل السمات، وتتحدث كل 40 دقيقة تقريبًا. يبقى الموقع التقريبي (مقرّبًا إلى نحو 1 كم) على جهازك فقط ويُفحص عبر خادمنا لدى MET Norway. الميزة متوقفة افتراضيًا. تحت المفتاح مكتوب ما هو الطقس في الخارج الآن – مثلًا ⛅ غائم جزئيًا، ولهذا تظهر في السماء شمس وغيوم معًا.",
    faq_q_good_things: "ما هو \"3 أشياء جميلة من اليوم\"؟",
