    faq_a_home_focus: "بالضغط على ◎ أعلى الشاشة الرئيسية يختفي كل شيء ما عدا الشيء الوحيد الآن – ما يحدث في هذه الساعة، أو الشيء التالي في قائمة اليوم – مع ✓ كبيرة، وملاحظة سريعة. بعد ✓ يظهر الشيء التالي. «وضع التركيز ✕» في الأعلى يعيد كل شيء.",
    faq_a_home_search: "افتح القائمة ☰ – البحث في أعلاها تمامًا. اكتب حرفين على الأقل: تأتي النتائج من ملاحظاتك وقائمة التسوق والتقويم والوصفات والدفاتر (العناوين ونص الصفحات) والأهداف والجداول والكتب، مرتّبة حسب النوع – المس نتيجة للانتقال إليها مباشرة.",
    faq_a_my_day: "يجمع «يومي» ما كان يُعرف بـ«لمحة عن اليوم» و«روتيني» على خط زمني واحد. في أسفل الشاشة الرئيسية يظهر ما أُنجز، وما يحدث الآن أو التالي (مع ✓ سريعة)، وبجانب العنوان كوب ماء بلمسة +1. بالضغط عليه (أو سحبه للأعلى) يُفتح اليوم كله: في الأعلى ما ليس له وقت، ثم كل شيء حسب الساعة – مهام التقويم وأحداثه واجتماعاته، والمواعيد الأسبوعية الثابتة، وروتين اليوم، والخطوات الصغيرة للأهداف، ووجبات New Me – مع خط يشير إلى الآن. يمكن التصفية حسب المهام أو الروتين أو الاجتماعات والمناسبات. علامة ✓ هنا هي نفسها في كل مكان آخر (روتيني، أهدافي، التقويم) وتفتح زهرة أقحوان في الركن. «تعديل روتيني» يفتح «روتيني» (وهو موجود في القائمة أيضًا)، و«＋ إضافة لليوم» يضيف مهمة لليوم. لمس عنوان \"يومي\" (أو الشريط الصغير في الأعلى) يغلقه مرة أخرى.",
