    faq_a_table_shopping_link: "في عمود ✓ المرتبط بقائمة التسوق (مثل «المكوّنات متوفرة» في «وجبات الأسبوع») يوجد 🛒 بجانب كل صف لم يُحدَّد بعد. ضغطة واحدة تضيفه إلى قائمة التسوق – مرة واحدة فقط، دون تكرار. حدِّده هنا ✓ فيخرج من القائمة؛ احذفه من القائمة فلا يعود يظهر هنا على أنه «في القائمة»؛ وعلِّمه في القائمة كمشترى فيحصل الصف هنا على ✓ تلقائيًا. يمكن ربط أي عمود ✓ أو فصله من إعدادات العمود.",
