    nb_tools_label: "أدوات الرسم",
    faq_a_table_views: "داخل الجدول يمكن التبديل بين ثلاث طرق عرض في الأعلى: جدول (يبقى العمود الأول ثابتًا أثناء التمرير جانبًا، والصف الأخير يجمع الأرقام ويعدّ علامات ✓)، وبطاقات (كل صف كبطاقة)، ولوحة (البطاقات مجمّعة حسب عمود «اختيار» مثل الحالة – سحب البطاقة إلى عمود آخر يغيّر قيمتها). لمسة على عنوان عمود أو على ↕ ترتيب ترتّب الصفوف، وتصفية تعرض جزءًا منها فقط؛ والجدول يتذكر الاثنين. لمسة على أي صف تفتحه كبطاقة كاملة للتعديل، و＋ عمود يضيف عمودًا فورًا. وفي ⋯ توجد قائمة الأعمدة، والاسم والأيقونة والجيب، وحذف الجدول.",
