    apptour_g_today_text: "الخطوات الصغيرة لكل الأهداف لهذا اليوم، ولكل منها ✓ سريعة. وتظهر أيضًا في «يومي».",
    apptour_g_path_text: "المحطات التي أصبحت خلفنا، وحجر اليوم المتوهّج، والكأس في النهاية. ✓ صغيرة واحدة في اليوم تكفي للتقدّم – لا حاجة إلى 10.",
