    faq_a_new_me_tour: "مباشرة بعد الشراء وملء الاستبيان القصير، تعرض جولة قصيرة اللعبة: الشريط العلوي، والمهمة التالية، والأدوات على الجانبين، وتحدّي الأسبوع، والحقيبة السحرية، وخريطة العالم، وشخصيتك Me، والباب 1 إلى الغرفة السرية. يمكن إعادة مشاهدتها في أي وقت من ⚙️ الإعدادات > 🧭 جولة في New Me – ويمكن هناك أيضًا تغيير الاسم الكامل من الاستبيان. قبل الشراء، يظهر بجانب New Me في القائمة 🔒، والضغط عليه يفتح صفحة بكل ما هو مشمول.",
