    nm_tour_swap_text: "🔄 يبدّل الوجبة – من القائمة أو الوجبات المحفوظة أو بالكتابة للذكاء الاصطناعي، لليوم أو من الآن فصاعدًا. ⭐ يحفظها، ➖ يزيلها من القائمة.",
