    faq_a_new_me_advanced: "يُفتح الوضع المتقدم مع الهدية، بعد التحديات الـ20 كلها، ويمكن تشغيله أو إيقافه في 🎁 هديتك. يمنح New Me مظهرًا ذهبيًا، وبناء قائمة حرًا – كل تبديل يعرض كل الخيارات بلا حد للسعرات – وشاشة 📊 إحصاءات متقدمة: سعرات آخر 30 يومًا مقارنة بالخطة، والأيام الجيدة حسب يوم الأسبوع، واتجاه الوزن مع تقدير لموعد بلوغ الهدف، ومتوسطات تسجيل المساء، وسجل التحديات.",
