    nm_gift_title: "هديتك",
    faq_a_new_me_letter_gift: "في بداية New Me (أو لاحقًا في التحديات) يمكن كتابة رسالة إلى نفسك في المستقبل. بعد ختمها لا يمكن قراءتها أو تعديلها حتى تُفتح: في الزجاجة القادمة من البحر في الغرفة السرية، أو عند إتمام جميع التحديات العشرين – وهناك تنتظر هدية أيضًا.",
    faq_q_new_me_letter_gift: "ما هي الرسالة من الماضي؟",
    faq_a_new_me_challenges: "في 🏆 التحديات يوجد 20 تحديًا: 10 كبيرة (مثل 5 أيام بلا سكر، أو أسبوع بلا كربوهيدرات، أو خسارة 4 كغ في شهر – عجز في السعرات وتمرين وبلا سكر كل يوم) و10 صغيرة – عادات صغيرة لمدة أسبوع، مثل القهوة بالقرفة بلا سكر. عند اختيار تحدٍّ يُسأل متى نبدأ: اليوم أو غدًا أو الأسبوع القادم أو في تاريخ آخر. يمكن لتحدٍّ كبير وتحدٍّ صغير أن يجريا معًا. التحدي الجاري يظهر في أعلى القائمة وفي يومي، مع ✓ لليوم. كل أسبوع من التحدي يأتي بيوم حر (🍕) لا يكسره، واليوم غير المُعلَّم يُحسب يومًا حرًا – يمكن تعليم اليوم وأمس أيضًا. بعض الأيام تُعلَّم تلقائيًا: تمرين مدته 20 دقيقة في متابعة التمارين، أو وجبات القائمة مع ✓. لكل تحدٍّ زر ⓘ يوضح ما الذي يُحتسب بالضبط (مثل القائمة الكاملة للكربوهيدرات) – في التحدي نفسه وبجانبه في يومي. وتحتها، في 🌱 التطوّر الشخصي، 48 تحديًا صغيرًا لأسبوع واحد (لا تُحتسب ضمن العشرين) – انظر «ما هو تحدّي الأسبوع؟».",
