    faq_a_workout_calories: "نعم. لكل تمرين تقدير للسعرات المحروقة – حسب النوع والمدة وآخر وزن مسجّل (وفي الجري وركوب الدراجة أيضًا حسب السرعة عند إدخال المسافة). يظهر في قائمة التمارين وفي الملخص الشهري (الحرق)، ويُضاف إلى ميزانية سعرات ذلك اليوم: في متتبع الوجبات اليومي وفي مقاييس السعرات الحرارية والوزن وفي حلقة New Me. إنه تقدير، لذلك يظهر مع ~.",
    faq_q_workout_calories: "هل تُحسب التمارين في سعرات اليوم؟",
    faq_a_new_me_flexible_menu: "نعم. في الاستبيان وفي الإعدادات يُختار عدد الوجبات في اليوم – وجبتان + وجبة خفيفة / وجبتان + عشاء خفيف / وجبتان + وجبة خفيفة + عشاء خفيف – و➖ في بطاقة الوجبة يحذفها (تبقى 3 على الأقل)؛ و«➕ إعادة إلى القائمة» يعيدها. وفي كل الأحوال تبقى سعرات اليوم كما هي: ما يُحذف يُوزَّع على باقي الوجبات، وتحت كل وجبة يظهر ما أُضيف إليها وما يمكن إضافته. ✏️ تعديل في الوجبة يفتح نصّها – غيّر ما تريد (مثلًا بدون خبز أو مع بيضة إضافية) فيحسب الذكاء الاصطناعي السعرات والبروتين من جديد. 🔄 تبديل يعرض خيارات من القائمة و⭐ المحفوظة و✨ كتابة للذكاء الاصطناعي؛ وكل تغيير يمكن أن يكون لليوم فقط أو من الآن فصاعدًا. وفي نهاية «اليوم كله» يوجد ➕ إضافة طعام – اكتب ما أُكل خارج القائمة، فيحسبه الذكاء الاصطناعي ويضيفه إلى اليوم (✕ يحذفه).",
    faq_q_new_me_flexible_menu: "هل يمكن تغيير عدد الوجبات في New Me، أو تناول وجبة خاصة؟",
