    nm_story_out_text: "نودلز + صدر دجاج + ملعقة زيت + صلصة: تسجيل كل مكوّن على حدة يعطي تقديرًا أفضل بكثير.",
    nm_story_out_title: "الأكل خارج المنزل؟ تفكيك الطبق",
    nm_story_weekly_text: "الجسم يعمل وفق متوسط أسبوعي، لا وفق يوم واحد. لا حاجة إلى التعويض أو تخطي الوجبات – يكفي الاستمرار كالمعتاد.",
