    nm_story_after_text: "يكفي اختيار النسخة المطبوخة في قاعدة البيانات – مثل «أرز أبيض مطبوخ» وليس «أرز جاف».",
    nm_story_after_title: "الوزن بعد الطهي؟ ممتاز أيضًا",
    nm_story_pot_text: "تم وزن القدر كله وحسابه مسبقًا؟ يكفي تقسيم الطبق الجاهز إلى حصص متساوية – دون وزن من جديد.",
