    nm_goal_reminder: "هدفك أمام عينيك دائمًا",
    faq_a_share_whatsapp: "يوجد خيار للمشاركة في عدة أماكن: «شارك هذا الإنجاز» في شاشة الاحتفال عند تحقيق هدف، و📤 في الوصفة، و📤 بجانب التمرين في قسم «الرياضة»، و«✨ مشاركة التطبيق» في الإعدادات. ثم يكفي اختيار WhatsApp أو البريد الإلكتروني أو النسخ. تخرج الرسالة مرتّبة وأنيقة مع التفاصيل – في الهدف: التقدّم، والمدة التي استغرقها، والمكافأة؛ وفي الوصفة: المكوّنات وخطوات التحضير؛ وفي التمرين: الوقت والمسافة والصورة. وفي أسفل الرسالة يوجد دائمًا رابط صغير إلى التطبيق، ليتمكّن كل من يرغب من الدخول مباشرة. ولا يزال بالإمكان تعديل النص في WhatsApp قبل الإرسال.",
    faq_q_share_whatsapp: "كيف أشارك هدفًا أو وصفة أو تمرينًا على WhatsApp؟",
    sport_share_closing_3: "نواصل الحركة",
