    vision_focus_ribbon: "🎯 هدف الشهر",
    vision_tagline: "أهداف كبيرة، خطوات صغيرة.",
    faq_a_app_tour: "تُفتح الجولة تلقائيًا مرة واحدة عند الدخول الأول. تبدأ بأجزائها – لمسة على جزء تنقل إليه مباشرة – ثم تعرض كل أجزاء التطبيق (الشاشة الرئيسية ومساعد الذكاء الاصطناعي وكل عنصر في القائمة) ومجموعات الإعدادات الخمس، لكل منها شرح قصير، وتلقي نظرة إلى داخل بعضها (مثل مسار هدف تجريبي والحقيبة وGoogle Calendar). «متابعة» للتقدم، و«رجوع» للعودة، و«تخطي هذا الجزء» للانتقال إلى الجزء التالي، و✕ لإغلاق الجولة. يمكن مشاهدتها مجددًا في أي وقت من الإعدادات > المساعدة والاستخدام > جولة التطبيق، والمتابعة من حيث توقفت. «متابعة» و«رجوع» دائمًا في المكان نفسه أسفل الشاشة، وعلى الكمبيوتر تعمل أيضًا أسهم لوحة المفاتيح.",
    faq_q_app_tour: "كيف يمكن مشاهدة جولة التطبيق مرة أخرى؟",
    apptour_done_text: "هل من سؤال؟ المساعدة والأسئلة الشائعة في الإعدادات تجيب عن كل شيء، وهذه الجولة متاحة دائمًا ضمن المساعدة والاستخدام.",
    apptour_done_title: "هذا كل شيء! 🎉",
