    apptour_m_myweek_text: "التقويم الشهري، والمهام الأسبوعية المتكررة مع التذكيرات، وكل الأحداث ذات التاريخ. ومفكرة ورقية لاجتماعات الأسبوع 🤝.",
    apptour_m_newme_link: "كل شيء يُحتسب في متتبع الوجبات اليومي وفي يومي؛ والوزن مشترك مع مقاييس السعرات الحرارية والوزن.",
    apptour_m_newme_text: "خطة وجبات بـ 1,300 / 1,500 سعرة حرارية داخل عالم لعبة سحري: قائمة اليوم مع ✓، والتبديل بثلاث طرق – من القائمة، أو من الوجبات المحفوظة، أو بكتابة ما تمّ أكله للذكاء الاصطناعي فيحسب السعرات – وقائمة تسوق، وتذكيرات الوجبات، ورحلة تقدّم مع إنجازات وقياسات وصور. وأيضًا 🏆 20 تحديًا – مع هدية في النهاية – وتحدّي الأسبوع.",
