    apptour_peek_text: "كل ما يحدث اليوم في مكان واحد – المهام والاجتماعات والروتين والخطوات الصغيرة على خط زمني واحد. التحديد بـ ✓ من هنا مباشرة.",
    apptour_date_text: "الضغط عليه يفتح نظرة سريعة على التقويم الشهري – مع إمكانية إضافة شيء فورًا.",
