    table_select_option_delete_title: "حذف الخيار",
    faq_a_other_manual_option: "في كل مكان يتم فيه الاختيار من قائمة خيارات، يوجد أيضًا '✏️ أخرى' - يكفي اختياره وكتابة المطلوب بالضبط. في جدول يحتوي على عمود اختيار (مثل 'صلة القرابة' في جدول الهدايا)، يتم النقر على الخلية واختيار '✏️ أخرى' وكتابة القيمة (مثل 'ابن الأخ') ثم النقر على إضافة - فتُحفظ كخيار جديد في ذلك العمود، وفي المرة القادمة تكون موجودة في القائمة مسبقًا. علامة × الصغيرة بجانب كل خيار في تلك القائمة تحذف الخيار من العمود. وعند اختيار أيقونة للجدول تتوفر أيقونات كثيرة (منها ملاحظات لاصقة ملوّنة). وتعمل الطريقة نفسها مع فئات الوجبات المحفوظة، وفئات الوصفات، وفئات المصروفات المتكررة (تُحفظ كفئة شخصية جديدة) وفئات الأهداف في «أهدافي».",
