    receipts_total_tile: "إجمالي كل الإيصالات",
    faq_a_quick_note_apple: "الـ 🍎 بجانب 📝 و🛒 في نافذة الملاحظات هي اختصار لتسجيل إحدى الوجبات المحفوظة بسرعة في متتبع الوجبات اليومي لليوم. وهي مفعّلة افتراضيًا - وعند عدم الحاجة إليها يمكن إيقافها من الإعدادات > التخصيص والتقويم ('إظهار اختصار 🍎 للوجبات المحفوظة في نافذة الملاحظات')، وإعادة تفعيلها من هناك في أي وقت.",
    faq_q_quick_note_apple: "ما هي 🍎 في نافذة الملاحظات، وهل يمكن إخفاؤها؟",
    settings_quick_note_apple_label: "إظهار اختصار 🍎 للوجبات المحفوظة في نافذة الملاحظات",
    faq_a_vision_board_today: "في «أهدافي»، تحت مسار الهدف (في «الخطة»)، يكفي الضغط على 📅 بجانب المحطة واختيار تاريخ. ويمكن أيضًا تفعيل «🔁 كل أسبوع حتى الإنجاز» – وعندها تعود المحطة كل أسبوع في اليوم نفسه حتى تحديدها كمنجزة مرة واحدة. وتظهر المحطة في ذلك اليوم في «يومي» وفي التقويم (وفي Google Calendar إذا كان متصلًا)، ويُظهر الزر موعد جدولتها. ووضع ✓ في أحد المكانين يحدّدها في الآخر ويُقدّم مسار الهدف. والضغط على 📅 مرة أخرى يتيح تغيير التاريخ أو إزالتها من التقويم. وحذف مهمة لمرة واحدة من التقويم يحذف المحطة من الهدف أيضًا؛ أما حذف أسبوع واحد من تذكير أسبوعي فيزيل ذلك الأسبوع فقط.",
    faq_q_vision_board_today: "كيف يمكن إضافة محطة من هدف إلى التقويم (📅)؟",
    vision_milestone_already_today: "هذه الخطوة موجودة بالفعل في مهام اليوم.",
