    nm_drink_add: "إضافة",
    nm_drink_name_ph: "مشروب (مثل عصير)",
    nm_drinks_hint: "يكفي كتابة اسم المشروب – تُحسب السعرات تلقائيًا، ويمكن تغيير الرقم.",
    nm_slot_drinks: "المشروبات",
    faq_a_new_me_tracking: "الضغط على المهمة التالية في أعلى New Me ثم على ✓ أكلتُ يعلّم الوجبة التالية كمأكولة – القائمة الكاملة مع ✓ لكل وجبة موجودة في «اليوم كله» على الجانب، ووجبات اليوم تظهر أيضًا في يومي على الشاشة الرئيسية – والضغط على إحداها هناك (أو تمرير الفأرة فوقها) يُظهر بالضبط ما الذي يُؤكل، مع ✓ وتبديل. كل شيء متزامن مع متتبع الوجبات اليومي: وجبات الخطة والمشروبات وكل ما يُضاف في مكان آخر (مثل قهوة من الإضافة السريعة) تُحسب معًا في New Me وفي يومي – لا يُستبدل شيء كُتب من قبل، وإزالة ✓ تزيل جزء New Me فقط. عندما تُعلَّم كل وجبات اليوم يكون هناك احتفال صغير. تحت «المشروبات» تُسجَّل مشروبات اليوم – كلها معًا حتى ~150 سعرة، أي نحو 3 مشروبات حتى ~50 سعرة لكل منها. يكفي كتابة اسم المشروب فتُملأ السعرات تلقائيًا بالذكاء الاصطناعي. في سطرَي القهوة/الشاي يوجد أيضًا حقل «حليب؟ كم؟» (مثل «قليل» أو «50 مل»)، ويتحدّث الحساب؛ ويمكن تغيير الرقم قبل الإضافة وبعدها أيضًا. المشروب الذي له اسم وسعرات يُحفظ تلقائيًا بمجرد الانتقال إلى غيره – الضغط على إضافة اختياري. الضغط على ☆ بجانب مشروب يحفظه كمشروب معتاد – تظهر المشروبات المعتادة كأزرار أعلى بطاقة المشروبات، وضغطة واحدة تضيفها إلى اليوم. ⭐ يحفظ الوجبة كوجبة محفوظة. «الجدول اليومي» يعرض ما أُكل مع السعرات والبروتين. ويفتحه 💎 الصغير بجانب وضع التركيز أعلى الشاشة الرئيسية مباشرة. قيم السعرات والبروتين تقديرات بالذكاء الاصطناعي وقد تحتوي على أخطاء. لم تُؤكل الوجبة كلها؟ تحت وجبة معلَّمة، يزيل «لم آكل كل شيء؟» ربع الحصة أو نصفها أو ثلاثة أرباعها – أو ما يُكتب، محسوبًا – وتتحدّث سعرات اليوم.",
    faq_q_new_me_tracking: "كيف تعمل علامة ✓ والتبديل والسعرات الحرارية في New Me؟",
    faq_a_new_me_what: "New Me برنامج قائمة يومية منفصل بخطتين جاهزتين – 1,300 أو 1,500 سعرة حرارية – من وجبتين رئيسيتين ووجبتين خفيفتين، مع 3 خيارات لكل منها. يشمل كل مزايا بريميوم. السعر: ‎$11.99 شهريًا (إلغاء في أي وقت) أو ‎$99.99 مرة واحدة مدى الحياة. يُفتح من 💎 New Me في القائمة. قبل البدء يوجد استبيان قصير يبدأ بإخلاء مسؤولية طبي يجب قبوله. البرنامج معلومات عامة فقط ولا يغني عن الطبيب أو أخصائي التغذية السريرية.",
