    daily_greeting_morning: "صباح الخير!", daily_greeting_afternoon: "طاب يومك!", daily_greeting_evening: "مساء الخير!", daily_greeting_night: "ليلة سعيدة!", calorie_monthly_view_title: "العرض الشهري", calorie_monthly_avg_label: "المتوسط اليومي:", calorie_monthly_avg_empty: "لا توجد بيانات مسجلة بعد هذا الشهر", calorie_monthly_day_total_label: "إجمالي اليوم:", notes_ai_added_shopping: "تمت الإضافة إلى قائمة التسوق الخاصة بك", quick_note_dest_notes: "📝 الملاحظات", quick_note_dest_shopping: "🛒 قائمة التسوق",
    faq_q_calorie_monthly_view: "كيف أرى سجل السعرات الحرارية لشهر كامل؟", faq_a_calorie_monthly_view: "يحتوي قسم مقاييس السعرات الحرارية والوزن على بطاقة 'العرض الشهري' مع تقويم - كل يوم سجّلت فيه طعامًا يظهر عليه نقطة، ويُعرض متوسط السعرات اليومي لذلك الشهر أعلى الجدول. اضغط على أي يوم لترى بالضبط ماذا أكلت وإجماليه. نفس التفصيل مُدرَج أيضًا عند تنزيل تقريرك الشخصي (PDF) من الإعدادات، إذا كان قسم مقاييس السعرات الحرارية والوزن محددًا.",
    faq_q_calorie_stats_total_vs_average: "هل الأرقام الأسبوعية/الشهرية في مقاييس السعرات الحرارية والوزن هي إجمالي أم متوسط؟", faq_a_calorie_stats_total_vs_average: "كلاهما - الرقم الكبير هو الإجمالي (المجموع) لكل ما تم تسجيله في الأسبوع/الشهر التقويمي الحالي، والسطر الصغير أسفله هو المتوسط اليومي. يُحسب المتوسط فقط على الأيام التي سجّلت فيها فعلاً شيئًا، وليس على 7 أيام أو على الشهر كاملاً - اليوم الذي لم يُسجَّل فيه أي شيء يُتخطى ببساطة، فهو لا يُحتسب كصفر ولا يُخفّض المتوسط.",
    faq_q_weight_note: "هل يمكنني إضافة ملاحظة إلى تسجيل الوزن؟", faq_a_weight_note: "نعم - هناك حقل ملاحظة اختياري بجانب حقلي الوزن والتاريخ في تتبع الوزن الدوري (يوجد في أسفل التغذية والمقاييس > مقاييس السعرات الحرارية والوزن، تحت ⚖️). يمكن استخدامه لإضافة سياق مثل \"بعد التمرين\" أو \"وزن الصباح\" - يظهر بجانب ذلك التسجيل في قائمة السجل.",
