    daily_focus_c6_d0: "أن أنصت باهتمام حقيقي، لا أن أنتظر دوري في الكلام فقط", daily_focus_c6_d1: "أن أتذكر أن كل شخص يحمل شيئًا لا يظهر للعين", daily_focus_c6_d2: "أن أنشر طاقة دافئة ومرحبة من حولي", daily_focus_c6_d3: "أن أحافظ على الانفتاح والاحترام في تواصلي", daily_focus_c6_d4: "أن أرى الجانب الجميل في من حولي", daily_focus_c6_d5: "أن أقول كلمة طيبة لمن يحتاجها اليوم",
