    daily_focus_p5_d4_s1: "أن أحافظ على وتيرة تقدم صحية تناسب مسارًا طويلًا", daily_focus_p5_d4_s2: "أن آخذ نفسًا عميقًا وأعيد الاتصال بمعنى ما أفعله", daily_focus_p5_d4_s3: "أن أثق بالأسس القوية التي بنيتها على مدار العام", daily_focus_p5_d4_s4: "أن أنفّذ خطوات واسعة النطاق بثقة كاملة", daily_focus_p5_d4_s5: "أن أقدّر النمو الشخصي والمهني الذي مررت به",
