    faq_q_daily_focus_prompt: "ما هو التذكير الصغير الذي يسأل عن أهم شيء أفعله اليوم؟", faq_a_daily_focus_prompt: "إنه تذكير يومي ضمن Premium: مرة واحدة يوميًا تظهر شارة صغيرة «1» على أيقونة مساعد الذكاء الاصطناعي. النقر على الشارة يفتح فقاعة تسأل عمّا هو الأهم لك اليوم، وتظهر فيها مباشرةً 5 اقتراحات جاهزة (تتغير يوميًا وتتنقل بين موضوعات مختلفة على مدار عام كامل لتبقى متجددة) بالإضافة إلى 'غير ذلك' لكتابة اقتراحك الخاص - ويمكن اختيار أكثر من واحد. بعد النقر على إضافة، تظهر الاختيارات كوسوم تذكير صغيرة في أعلى 'يومي' (وهي ليست مهامًا للتحديد). عند الإغلاق بـ✕ أو النقر خارجها، تبهت الشارة فقط لبقية اليوم بدلًا من أن تختفي. هذه الميزة مفعّلة افتراضيًا، ويمكن إيقافها من الإعدادات > التخصيص والتقويم. ليس يومًا مناسبًا؟ يكفي الضغط على «🌙 ليس اليوم» – تختفي الشارة حتى الغد، ثم يعود السؤال كالمعتاد. أحد الاقتراحات يأتي من حياتك – الخطوة التالية في هدف الشهر أو قراءة اليوم. كل يوم يبدأ من جديد.",
